select c.claim_id, c.claimant_id, c.partner_id, c.program_id, c.sku_id, c.claim_date, c.rebate_amount, cast(f.risk_score as integer) as risk_score, cast(f.risk_band as varchar) as risk_band, cast(f.is_amount_outlier as boolean) as is_amount_outlier, case when f.risk_band = "high" then true else false end as is_flagged_for_review, current_timestamp as model_built_ts from {{ ref("stg_claims") }} c join {{ ref("int_claim_features") }} f on c.claim_id = f.claim_id
